jsonTools.init:
function init(eli) {
  var SETTING_KEY = "ask_dock_enabled";
  var _enabled = true;
  var _handle = null, _backdrop = null, _panel = null, _panelBody = null;
  var _built = false, _isOpen = false, _hideTimer = null;

  // ── Kill switch via eli.settings (instant off, no uninstall) ──────
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register(SETTING_KEY, {
        default: true,
        type: "boolean",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "askDockEnabled" },
        apply: function (v) { _enabled = v !== false; _applyEnabled(); },
        adminPushable: true,
        describe: "Show the pull-down Ask ELI dock under the header",
      });
      _enabled = eli.settings.get(SETTING_KEY) !== false;
    }
  } catch (_e) {}

  // ── Position chrome relative to the live header bottom edge ───────
  function _headerBottom() {
    try {
      var h = document.querySelector(".header");
      if (h) {
        var r = h.getBoundingClientRect();
        if (r && r.bottom > 0) return Math.round(r.bottom);
      }
    } catch (_e) {}
    return 0;
  }
  function _positionChrome() {
    var top = _headerBottom();
    // Overlap the header's bottom edge by 1px so the handle reads as an
    // extension of the header (no visible seam).
    if (_handle) _handle.style.top = (top - 1) + "px";
    if (_backdrop) _backdrop.style.top = top + "px";
    if (_panel) {
      _panel.style.top = top + "px";
      // Open large — fill almost the whole area below the header, leaving a
      // thin backdrop strip at the bottom to tap-close.
      _panel.style.height = "calc(100vh - " + (top + 14) + "px)";
    }
  }

  // Make the handle visually part of the header by matching its live
  // background + text color (works across themes). Falls back to the
  // CSS navy/gold when the header bg is a gradient/transparent.
  function _matchHeaderLook() {
    if (!_handle) return;
    try {
      var h = document.querySelector(".header");
      if (!h) return;
      var cs = getComputedStyle(h);
      var bg = cs.backgroundColor;
      if (bg && bg !== "transparent" && bg.indexOf("rgba(0, 0, 0, 0)") === -1) {
        _handle.style.background = bg;
      }
      if (cs.color) _handle.style.color = cs.color;
    } catch (_e) {}
  }

  // ── Build the handle + panel once (idempotent) ───────────────────
  function _build() {
    if (_built) return;
    _built = true;

    _handle = document.createElement("button");
    _handle.type = "button";
    _handle.id = "_eli3_askdock_handle";
    _handle.className = "_eli3_askdock_handle";
    _handle.setAttribute("data-askdock", "1");
    _handle.title = "Ask ELI — open from anywhere";
    _handle.innerHTML =
      '<span class="_eli3_askdock_label">💬 Ask ELI</span>' +
      '<span class="_eli3_askdock_chev">▾</span>';
    _handle.onclick = function () { _isOpen ? _close() : _openDock(); };
    document.body.appendChild(_handle);

    _backdrop = document.createElement("div");
    _backdrop.id = "_eli3_askdock_backdrop";
    _backdrop.className = "_eli3_askdock_backdrop";
    _backdrop.setAttribute("data-askdock", "1");
    _backdrop.style.display = "none";
    _backdrop.onclick = _close;
    document.body.appendChild(_backdrop);

    _panel = document.createElement("div");
    _panel.id = "_eli3_askdock_panel";
    _panel.className = "_eli3_askdock_panel";
    _panel.setAttribute("data-askdock", "1");
    _panel.style.display = "none";
    _panel.innerHTML =
      '<div class="_eli3_askdock_phead">' +
        '<div class="_eli3_askdock_ptitle">🤖 Ask ELI</div>' +
        '<button type="button" class="_eli3_askdock_pclose" title="Close">✕</button>' +
      '</div>' +
      '<div class="_eli3_askdock_pbody" id="_eli3_askdock_pbody"></div>';
    document.body.appendChild(_panel);
    _panelBody = _panel.querySelector("#_eli3_askdock_pbody");
    _panel.querySelector("._eli3_askdock_pclose").onclick = _close;

    _positionChrome();
    try { window.addEventListener("resize", _positionChrome); } catch (_e) {}
  }

  // ── Open / close ─────────────────────────────────────────────────
  function _openDock() {
    if (!_enabled) return;
    _build();
    if (_hideTimer) { clearTimeout(_hideTimer); _hideTimer = null; }
    _positionChrome();
    _panel.style.display = "flex";
    _backdrop.style.display = "block";
    // Fresh render each open: clear, then render Ask ELI into the panel body.
    // Conversation persists via ask_eli's _sharedSessionHistory; the doc
    // mapping/index is docHash-cached so this does NOT re-map.
    if (_panelBody) _panelBody.innerHTML = "";
    _isOpen = true;
    requestAnimationFrame(function () {
      if (_backdrop) _backdrop.classList.add("_eli3_askdock_show");
      if (_panel) _panel.classList.add("_eli3_askdock_open");
      if (_handle) _handle.classList.add("_eli3_askdock_open");
    });
    var render = function () {
      if (!_isOpen) return; // user closed before load finished
      try { eli.dispatch("ask_eli", "openPanel", { mount: _panelBody, onClose: _close }); }
      catch (e) { if (typeof showToast === "function") showToast("Ask ELI failed to open: " + (e && e.message || "unknown"), "err"); }
    };
    if (eli.tools && typeof eli.tools.ensureLoaded === "function") {
      eli.tools.ensureLoaded("ask_eli").then(render).catch(render);
    } else { render(); }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAskDock"); } catch (_e) {}
  }

  function _close() {
    if (!_panel) return;
    _isOpen = false;
    if (_backdrop) _backdrop.classList.remove("_eli3_askdock_show");
    if (_panel) _panel.classList.remove("_eli3_askdock_open");
    if (_handle) _handle.classList.remove("_eli3_askdock_open");
    // After the slide-out transition, hide + tear down the Ask ELI instance
    // (clearing the body fires ask_eli's DOM-removal watchdog → frees its
    // selection poller). Conversation is safe in _sharedSessionHistory.
    _hideTimer = setTimeout(function () {
      if (_isOpen) return;
      if (_panel) _panel.style.display = "none";
      if (_backdrop) _backdrop.style.display = "none";
      if (_panelBody) _panelBody.innerHTML = "";
    }, 300);
  }

  // ── Enable/disable (kill switch) ─────────────────────────────────
  function _applyEnabled() {
    if (!_enabled) {
      _close();
      if (_handle) _handle.style.display = "none";
    } else {
      if (!_built) _build();
      if (_handle) _handle.style.display = "";
      _positionChrome();
    }
  }

  // ── Boot: build the handle (only if enabled) ─────────────────────
  if (_enabled) {
    // Header may not be in the DOM at first init tick — retry briefly.
    var tries = 0;
    (function _ensure() {
      _build();
      _applyEnabled();
      // Re-position + re-skin once the header settles (theme/layout shifts).
      _positionChrome();
      _matchHeaderLook();
      if (_headerBottom() === 0 && tries++ < 20) setTimeout(_ensure, 300);
    })();
  }

  // Auto-close when the user navigates Home (kernel emits this from _goHome).
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("home:navigate", function () { _close(); });
    }
  } catch (_e) {}

  eli.register({
    ask_dock: { open: _openDock, close: _close },
  });

  eli.log.event("tool", "ask_dock_initialized", { enabled: _enabled });
}

jsonTools.css:
/* ask_dock — pull-down Ask ELI handle + slide-down panel. All selectors
   namespaced _eli3_askdock_* so removal is clean (delete this file + the
   tool). Navy/gold to match ELI chrome. Light panel body (dialog convention). */

/* Pull-down handle — attached to the header's bottom edge, centered. */
._eli3_askdock_handle {
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  /* top set by JS to the header's bottom (overlapped 1px, no seam) */
  z-index: 8000;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 2px 18px 4px;
  /* background + color are overwritten by JS to match the live header so the
     handle reads as an extension of it; these are the fallback. */
  background: linear-gradient(180deg, #1e293b 0%, #0f172a 100%);
  color: #e7c14e;
  border: none;
  border-bottom: 2px solid #c9a227; /* gold lip — the only accent */
  border-radius: 0 0 9px 9px;
  box-shadow: 0 3px 6px rgba(15, 23, 42, 0.18);
  cursor: pointer;
  font-family: inherit;
  transition: filter 0.15s ease, box-shadow 0.15s ease;
}
._eli3_askdock_handle:hover {
  filter: brightness(1.14);
  box-shadow: 0 4px 9px rgba(15, 23, 42, 0.26);
}
/* Gold chevron — stays gold even when the label matches the header text. */
._eli3_askdock_chev { color: #e7c14e; }
._eli3_askdock_label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  line-height: 1;
}
._eli3_askdock_chev {
  font-size: 11px;
  line-height: 1;
  transition: transform 0.25s ease;
}
._eli3_askdock_handle._eli3_askdock_open ._eli3_askdock_chev {
  transform: rotate(180deg);
}

/* Dimming backdrop below the header */
._eli3_askdock_backdrop {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  /* top set by JS */
  z-index: 7990;
  background: rgba(15, 23, 42, 0);
  pointer-events: none;
  transition: background 0.25s ease;
}
._eli3_askdock_backdrop._eli3_askdock_show {
  background: rgba(15, 23, 42, 0.42);
  pointer-events: auto;
}

/* Slide-down panel */
._eli3_askdock_panel {
  position: fixed;
  left: 0;
  right: 0;
  /* top + max-height set by JS */
  z-index: 8001;
  display: flex;
  flex-direction: column;
  background: #f8fafc;
  border-bottom: 3px solid #c9a227;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.42);
  transform: translateY(-110%);
  transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}
._eli3_askdock_panel._eli3_askdock_open {
  transform: translateY(0);
}

._eli3_askdock_phead {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
}
._eli3_askdock_ptitle {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.2px;
}
._eli3_askdock_pclose {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #cbd5e1;
  width: 28px;
  height: 28px;
  border-radius: 7px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s ease;
}
._eli3_askdock_pclose:hover {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
}

/* Body mount — Ask ELI's chat renders in here and fills it */
._eli3_askdock_pbody {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  position: relative;
}
._eli3_askdock_pbody > * {
  height: 100%;
}
